{
  "name": "gestao-tarefas-equipe",
  "version": "1.0.0",
  "description": "Sistema completo de gestão de tarefas de equipe com autenticação e sincronização em tempo real.",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "node server.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "bcryptjs": "^2.4.3",
    "jsonwebtoken": "^9.0.2",
    "cors": "^2.8.5",
    "body-parser": "^1.20.2",
